def longest_chain(pairs):
    if not pairs:
        return 0
    pairs.sort()
    n = len(pairs)
    dp = [1 for _ in range(n)] 
    for i in range(1, n):
        for j in range(i):
            if pairs[i][0] > pairs[j][1]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

