    n=d
    if n<0:
        return -1
    jumps = 0
    while n>0:
        if n-1>=0:
            n=n-1
            jumps+=1
        elif n-2>=0:
            n=n-2
            jumps+=1
        elif n-3>=0:
            n=n-3
