    if divi == None:
        return (0)
    x = len(divi)
    if x == 1:
        return (1)
    dp = [1] * x
    for i in range(1, x):
        for j in range(0, i):
            if divi[i] % divi[j] == 0 and 1+dp[j] > dp[i]:
                dp[i] = 1+dp[j]
    return max(dp)

def max_subset(a, n): 
    if (n == 0): 
        return 0
    if (n == 1): 
        return 1
    max_subset = 1
    for i in range(1, n): 
        cnt = max_subset(a, i) 
        if (abs(a[i] - a[i - 1]) == 1): 
            cnt = max(cnt, max_subset(a, i - 1) + 1) 
        max_subset = max(max_subset, cnt) 
    return max_subset

def largest_subset(arr):
    N = len(arr)
    dp = [1]*N
    parent = [-1]*N
    for i in range(N):
        for j in range(i):
            if arr[i]%arr[j]==0 and dp[i]<dp[j]+1:
                dp[i] = dp[j]+1
                parent[i] = j
    max_elem = -1
    max_index = -1
    for i in range(N):
        if dp[i] > max_elem:
            max_elem = dp[i]
            max_index = i
    result = []
    while max_index != -1:
        result.append(arr[max_index])
        max_index = parent[max_index]
    result.reverse()
    return result

