    dp = [[0 for x in range(n)] for y in range(n)]
    for i in range(n):
        dp[i][i] = matrix[i][i]
    for j in range(1,n):
        for i in range(n):
            if i == 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
