def find_max_average_path(matrix): 
    n = 3
    row = [0]*n
    col = [0]*n
    for i in range(n): 
        for j in range(n): 
            if (i == 0): 
                row[i] += matrix[i][j] 
            else: 
                row[i] += matrix[i][j] - matrix[i-1][j] 
            if (j == 0): 
                col[j] += matrix[i][j] 
            else: 
                col[j] += matrix[i][j] - matrix[i][j-1] 
    res = float('-inf') 
    for i in range(n): 
        for j in range(n): 
            if (i == 0 and j == 0): 
                ave = row[i]/2.0 + col[j]/2.0 
            else: 
                ave = row[i]/2.0 + col[j]/2.0 - row[i-1]/2.0 - col[j-1]/2.0 
            res = max(res, ave) 
    return float(res)

def max_avg_path(arr):
    n = len(arr)
    dp = [[0 for i in range(n)] for j in range(n)]
    dp[0][0] = arr[0][0]
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + arr[i][0]
        dp[0][i] = dp[0][i-1] + arr[0][i]
    for i in range(1,n):
        for j in range(1,n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + arr[i][j]
    return dp[n-1][n-1]/n

def max_average_path(A):
    n = len(A)
    dp = [[0 for i in range(n + 1)] for j in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            dp[i][j] = max(A[i - 1][j] + dp[i - 1][j],
                           A[i][j] + dp[i][j - 1],
                           A[i][j] + dp[i][j - 1] + dp[i - 1][j],
                           A[i][j] + dp[i][j - 1] + dp[i - 1][j - 1])
    return (dp[-1][-1]) / (n + (n - 1) / 2)

