def search(str, sub_str):
    count_occurrence = str.count(sub_str)
    start_index = 0
    while start_index < len(str):
        index = str.find(sub_str, start_index)
        if index == -1:
            break
        yield index, index + len(sub_str) - 1
        start_index = index + 1
    return count_occurrence

