def rgb_to_hsv(r,g,b):
    r = r/255
    g = g/255
    b = b/255
    minn = min(r, g, b)
    maxx = max(r, g, b)
    delta = maxx - minn
    h = 0
    if delta == 0:
        s = 0
    else:
        s = (maxx - minn) / maxx
    if s == 0:
        return 0
    if maxx == r:
        h = (g - b) / delta
    elif maxx == g:
        h = 2 + (b - r) / delta
    elif maxx == b:
        h = 4 + (r - g) / delta
    h *= 60
    if h < 0:
        h += 360
    return (h, s, maxx)

