def right_insertion_point(nums, val): 
    if not nums: 
        return 0
    left = 0
    right = len(nums) - 1
    while left <= right: 
        mid = (left + right) // 2
        if (nums[mid] < val): 
            left = mid + 1
        else: 
            right = mid - 1
    return left

