import heapq
def n_items_k_cheap(price_data,n):
  if n >= len(price_data):
    return price_data
  heap = []
  result = []
  for item in price_data:
    if len(heap) < n:
      heapq.heappush(heap, (item[1], item[0]))
    else:
      if heap[0][0] > item[1]:
        heapq.heappop(heap)
        heapq.heappush(heap, (item[1], item[0]))
    if len(heap) == n:
      result.append(heap[0][1])
  return result

