    if high < low: 
        return 0
    if high == low: 
        return low 
    mid = low + (high - low)/2
    mid = int(mid) 
    if arr[mid] <= arr[(mid + 1) % n] and arr[mid - 1] >= arr[(mid + n - 1) % n]: 
        return mid; 
    if arr[mid] <= arr[high]: 
        return count_Rotations_Range(arr, low, (mid - 1), n) 
