def spiral_matrix(n):
    matrix = np.arange(1, n * n + 1).reshape(n, n)
    row_begin, row_end = 0, len(matrix) - 1
    col_begin, col_end = 0, len(matrix[0]) - 1
    while row_begin <= row_end and col_begin <= col_end:
        for i in range(col_begin, col_end + 1):
            matrix[row_begin][i] = n * n + 1
        row_begin += 1
        for i in range(row_begin, row_end + 1):
            matrix[i][col_end] = n * n + 1
        col_end -= 1
        for i in range(col_end, col_begin - 1, -1):
            matrix[row_end][i] = n * n + 1
        row_end -= 1
        for i in range(row_end, row_begin - 1, -1):
            matrix[i][col_begin] = n * n + 1
        col_begin += 1
    return matrix

def spiral_matrix(n):
    matrix = [[0 for x in range(n)] for y in range(n)]
    num = 1
    for layer in range(int(n / 2)):
        i,j = layer,layer
        for y in range(j,n-layer):
            if matrix[layer][y] == 0:
                matrix[layer][y] = num
                num += 1
        for x in range(layer+1,n-layer):
            if matrix[x][y] == 0:
                matrix[x][y] = num
                num += 1
        for y in range(y-1,j,-1):
            if matrix[x][y] == 0:
                matrix[x][y] = num
                num += 1
        for x in range(x-1,layer,-1):
            if matrix[x][y] == 0:
                matrix[x][y] = num
                num += 1
    if n % 2 == 1:
        matrix[layer][layer] = num
    return matrix

