def find_Index(nums1, m, nums2, n): 
    i = m - 1
    j = n - 1
    last = m + n - 1
    while (last >= 0): 
        if j < 0: 
            break
        if i >= 0 and nums1[i] > nums2[j]: 
            nums1[last] = nums1[i] 
            last -= 1
            i -= 1
        else: 
            nums1[last] = nums2[j] 
            last -= 1
            j -= 1
    return nums1

