def largest_product_of_three(nums):
  n = len(nums)
  if n < 3:
    return None
  heap = []
  for num in nums:
    if len(heap) < 3:
      heapq.heappush(heap, num)
    else:
      heapq.heappushpop(heap, num)
  top3_smallest = sorted(heap, reverse=True)
  first = top3_smallest[0] * top3_smallest[1] * top3_smallest[2]
  second = top3_smallest[0] * nums[-2] * nums[-1]
  return max(first, second)

