def minimum_total(triangle):
    n = len(triangle)
    min_path_sum = [0] * n
    for i in range(n - 1, -1, -1):
        for j in range(len(triangle[i])):
            if j == 0:
                min_path_sum[j] = triangle[i][j] + min_path_sum[j]
            elif j == len(triangle[i]) - 1:
                min_path_sum[j] = triangle[i][j] + min_path_sum[j - 1]
            else:
                min_path_sum[j] = triangle[i][j] + min(min_path_sum[j], min_path_sum[j - 1])
    return min_path_sum

def minimum_Path_Sum(triangle):
    n = len(triangle)
    dp = [0] * (n+1)
    for i in range(n-1,-1,-1):
        for j in range(i+1):
            dp[j] = min(dp[j], dp[j+1]) + triangle[i][j]
    return dp[0]

def minimum_path_sum(tri, n): 
    for i in range(n-2, -1, -1): 
        for j in range(len(tri[i])): 
            tri[i][j] = min(tri[i][j] + tri[i + 1][j], tri[i][j] + tri[i + 1][j + 1]) 
    return tri[0][0]

def find_minimum_path_sum(triangle,N):
  two = [0]*N
  one = [0]*N
  one[0] = triangle[0][0]
  for i in range(1,N):
    two = one[:]
    for j in range(i+1):
      if j == 0:
        one[j] = one[j] + triangle[i][j]
      elif j == i:
        one[j] = two[j-1] + triangle[i][j]
      else:
        one[j] = min(one[j],two[j]) + triangle[i][j]
  return (one[N-1])

def min_sum_path(arr): 
    n = len(arr) 
    for i in range(n -2, -1, -1): 
        for j in range(i + 1): 
            arr[i][j] += min(arr[i + 1][j], arr[i + 1][j + 1])
    return arr[0][0]

def find_min_path(tri):
  n = len(tri)
  for i in range(n - 2, -1, -1):
    for j in range(len(tri[i])):
      tri[i][j] += min(tri[i + 1][j], tri[i + 1][j + 1])
  return tri[0][0]

def min_total_path_sum(triangle):
    res = triangle[-1]
    for row in range(len(triangle)-2,-1,-1):
        for i in range(len(triangle[row])):
            res[i] = min(res[i], res[i+1]) + triangle[row][i]
    return res[0]
